package org.example.controller

import org.example.model.Route
import org.example.service.RouteService
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*

@RestController
@RequestMapping("/api/routes")
class RouteController(private val routeService: RouteService) {

    @GetMapping
    fun getAllRoutes(): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getAllRoutes())
    }

    @GetMapping("/{id}")
    fun getRouteById(@PathVariable id: String): ResponseEntity<Route> {
        val route = routeService.getRouteById(id)
        return if (route != null) {
            ResponseEntity.ok(route)
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @GetMapping("/search/name")
    fun getRoutesByName(@RequestParam name: String): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByName(name))
    }

    @GetMapping("/search/region")
    fun getRoutesByRegion(@RequestParam region: String): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByRegion(region))
    }

    @GetMapping("/search/tag")
    fun getRoutesByTag(@RequestParam tag: String): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByTag(tag))
    }

    @GetMapping("/search/season")
    fun getRoutesBySeason(@RequestParam season: String): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesBySeason(season))
    }

    @GetMapping("/search/difficulty/max")
    fun getRoutesByMaxDifficulty(@RequestParam difficulty: Int): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByDifficultyLessThanEqual(difficulty))
    }

    @GetMapping("/search/difficulty/min")
    fun getRoutesByMinDifficulty(@RequestParam difficulty: Int): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByDifficultyGreaterThanEqual(difficulty))
    }

    @GetMapping("/search/distance")
    fun getRoutesByDistanceRange(
        @RequestParam minDistance: Double,
        @RequestParam maxDistance: Double
    ): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getRoutesByDistanceRange(minDistance, maxDistance))
    }

    @GetMapping("/popular")
    fun getPopularRoutes(@RequestParam(required = false, defaultValue = "0") minPopularity: Int): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getPopularRoutes(minPopularity))
    }

    @GetMapping("/top10")
    fun getTop10PopularRoutes(): ResponseEntity<List<Route>> {
        return ResponseEntity.ok(routeService.getTop10PopularRoutes())
    }

    @PostMapping
    fun createRoute(@RequestBody route: Route): ResponseEntity<Route> {
        return ResponseEntity.status(HttpStatus.CREATED).body(routeService.createRoute(route))
    }

    @PutMapping("/{id}")
    fun updateRoute(@PathVariable id: String, @RequestBody route: Route): ResponseEntity<Route> {
        val updatedRoute = routeService.updateRoute(id, route)
        return if (updatedRoute != null) {
            ResponseEntity.ok(updatedRoute)
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @DeleteMapping("/{id}")
    fun deleteRoute(@PathVariable id: String): ResponseEntity<Void> {
        val deleted = routeService.deleteRoute(id)
        return if (deleted) {
            ResponseEntity.noContent().build()
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @PostMapping("/{id}/popularity")
    fun incrementRoutePopularity(@PathVariable id: String): ResponseEntity<Route> {
        val route = routeService.incrementRoutePopularity(id)
        return if (route != null) {
            ResponseEntity.ok(route)
        } else {
            ResponseEntity.notFound().build()
        }
    }
}

