package org.example.controller

import org.example.dto.TripDto
import org.example.dto.toDto
import org.example.model.Trip
import org.example.service.TripService
import org.springframework.format.annotation.DateTimeFormat
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*
import java.time.LocalDateTime
import java.time.ZoneId

@RestController
@RequestMapping("/api/trips")
class TripController(private val tripService: TripService) {

    @GetMapping
    fun getAllTrips(): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getAllTrips().map { it.toDto() })
    }

    @GetMapping("/{id}")
    fun getTripById(@PathVariable id: String): ResponseEntity<TripDto> {
        val trip = tripService.getTripById(id)
        return if (trip != null) {
            ResponseEntity.ok(trip.toDto())
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @GetMapping("/search/name")
    fun getTripsByName(@RequestParam name: String): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByName(name).map { it.toDto() })
    }

    @GetMapping("/search/organizer")
    fun getTripsByOrganizerId(@RequestParam organizerId: String): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByOrganizerId(organizerId).map { it.toDto() })
    }

    @GetMapping("/search/status")
    fun getTripsByStatus(@RequestParam status: Int): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByStatus(status).map { it.toDto() })
    }

    @GetMapping("/search/startDate/after")
    fun getTripsByStartDateAfter(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) date: LocalDateTime
    ): ResponseEntity<List<TripDto>> {
        val instant = date.atZone(ZoneId.systemDefault()).toInstant()
        return ResponseEntity.ok(tripService.getTripsByStartDateAfter(instant).map { it.toDto() })
    }

    @GetMapping("/search/startDate/before")
    fun getTripsByStartDateBefore(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) date: LocalDateTime
    ): ResponseEntity<List<TripDto>> {
        val instant = date.atZone(ZoneId.systemDefault()).toInstant()
        return ResponseEntity.ok(tripService.getTripsByStartDateBefore(instant).map { it.toDto() })
    }

    @GetMapping("/search/startDate/between")
    fun getTripsByStartDateBetween(
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) startDate: LocalDateTime,
        @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) endDate: LocalDateTime
    ): ResponseEntity<List<TripDto>> {
        val startInstant = startDate.atZone(ZoneId.systemDefault()).toInstant()
        val endInstant = endDate.atZone(ZoneId.systemDefault()).toInstant()
        return ResponseEntity.ok(tripService.getTripsByStartDateBetween(startInstant, endInstant).map { it.toDto() })
    }

    @GetMapping("/search/participant")
    fun getTripsByParticipantUserId(@RequestParam userId: String): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByParticipantUserId(userId).map { it.toDto() })
    }

    @GetMapping("/search/route")
    fun getTripsByRouteId(@RequestParam routeId: String): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByRouteId(routeId).map { it.toDto() })
    }

    @GetMapping("/search/privacy")
    fun getTripsByPrivacySetting(@RequestParam privacySetting: String): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getTripsByPrivacySetting(privacySetting).map { it.toDto() })
    }

    @GetMapping("/recent")
    fun getRecentTrips(): ResponseEntity<List<TripDto>> {
        return ResponseEntity.ok(tripService.getRecentTrips().map { it.toDto() })
    }

    @PostMapping
    fun createTrip(@RequestBody trip: Trip): ResponseEntity<TripDto> {
        return ResponseEntity.status(HttpStatus.CREATED).body(tripService.createTrip(trip).toDto())
    }

    @PutMapping("/{id}")
    fun updateTrip(@PathVariable id: String, @RequestBody trip: Trip): ResponseEntity<TripDto> {
        val updatedTrip = tripService.updateTrip(id, trip)
        return if (updatedTrip != null) {
            ResponseEntity.ok(updatedTrip.toDto())
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @DeleteMapping("/{id}")
    fun deleteTrip(@PathVariable id: String): ResponseEntity<Void> {
        val deleted = tripService.deleteTrip(id)
        return if (deleted) {
            ResponseEntity.noContent().build()
        } else {
            ResponseEntity.notFound().build()
        }
    }

    @PatchMapping("/{id}/status")
    fun updateTripStatus(@PathVariable id: String, @RequestParam status: Int): ResponseEntity<TripDto> {
        val trip = tripService.updateTripStatus(id, status)
        return if (trip != null) {
            ResponseEntity.ok(trip.toDto())
        } else {
            ResponseEntity.notFound().build()
        }
    }
}

